/// <summary>
/// AVA/WEN/2024/11/11    AVA_012732_AddCustomerToCreditLimitGroup
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormControlEventHandler(formControlStr(CredManCreditLimitCustGroupLineAdd, OKCommandButton), FormControlEventType::Clicked)]
public static void OKCommandButton_OnClicked(FormControl sender, FormControlEventArgs e)
{
    CredManCreditLimitCustGroupLine groupLine;

    MultiSelectionHelper selection = MultiSelectionHelper::construct();
    selection.parmDatasource(sender.formRun().dataSource(formDataSourceStr(CredManCreditLimitCustGroupLineAdd, CustTable)));

    CustTable selectedRecord = selection.getFirst();

    while (selectedRecord)
    {
        select firstonly RecId from groupLine where groupLine.Company == selectedRecord.DataAreaId
                                                 && groupLine.CustAccount == selectedRecord.AccountNum;
        if (!groupLine.RecId)
        {
            if (CredManCustGuaranteeInsurance::avaCustCompanyGuaranteeExists(selectedRecord.DataAreaId, selectedRecord.AccountNum))
            {
                throw error("@NDX:NXACRLInsuranceError");
            }
        }

        selectedRecord = selection.getNext();
    }

}
